-- ÉTAPE 4 — VÉRIFICATIONS
-- ════════════════════════════════════════════════════════════════════════
-- 4a. attendu : 110 lignes, débit = crédit
SELECT COUNT(*) AS lignes, ROUND(SUM(debit),2) AS total_debit, ROUND(SUM(credit),2) AS total_credit FROM journal_comptable WHERE source_logiciel = 'script-reglements-2025';
-- 4b. attendu : AUCUNE ligne (pièce créée par ce script déséquilibrée)
SELECT piece, ROUND(SUM(debit)-SUM(credit),2) AS ecart FROM journal_comptable WHERE source_logiciel = 'script-reglements-2025' GROUP BY piece HAVING ABS(SUM(debit)-SUM(credit)) > 0.005;
-- 4c. attendu : uniquement les virements d'épargne de 500 € (une pièce qui crédite un compte et débite l'autre : 10 lignes au plus, toutes TXJ-…)
SELECT x.id, x.date_op, x.montant_banque, x.montant_512, x.piece FROM (
  SELECT t.id, t.date_op, t.ecriture_piece AS piece,
         COALESCE(t.credit,0)-COALESCE(t.debit,0) AS montant_banque,
         (SELECT SUM(COALESCE(j.debit,0)-COALESCE(j.credit,0)) FROM journal_comptable j WHERE j.piece=t.ecriture_piece AND j.compte LIKE '512%') AS montant_512
  FROM transactions t WHERE t.rapproche = 1 AND substr(t.date_op,7,4)||substr(t.date_op,4,2) >= '202507' AND t.ecriture_piece IS NOT NULL AND t.ecriture_piece <> '' AND (t.ecriture_pieces_json IS NULL OR t.ecriture_pieces_json = '' OR t.ecriture_pieces_json = '["'||t.ecriture_piece||'"]')) x
WHERE x.montant_512 IS NULL OR ABS(x.montant_banque - x.montant_512) > 0.005;
-- 4d. attendu : AUCUNE ligne (virement rattaché à une pièce d'une autre saison)
SELECT t.id, t.date_op, t.ecriture_piece, j.date_op AS date_piece
FROM transactions t JOIN journal_comptable j ON j.piece = t.ecriture_piece AND j.compte LIKE '512%'
WHERE t.rapproche = 1 AND substr(t.date_op,7,4)||substr(t.date_op,4,2)||substr(t.date_op,1,2) >= '20250701'
  AND ((substr(t.date_op,7,4)||substr(t.date_op,4,2)||substr(t.date_op,1,2)) < '20260701') <> (REPLACE(j.date_op,'-','') < '20260701');
-- 4e. attendu : AUCUNE ligne (ligne créée dont l'exercice ne correspond pas à la date)
SELECT id, piece, date_op, exercice_id FROM journal_comptable WHERE source_logiciel = 'script-reglements-2025'
  AND ((date_op < '2026-07-01' AND exercice_id <> '4c7ef360-e2bb-449b-bb40-e4715dcd8b2e') OR (date_op >= '2026-07-01' AND exercice_id <> '1c8cdf72-5240-4e1a-b9c1-c4f1e4ed2fbc'));
-- 4f. remises de chèques : somme des virements = somme des lignes 512 des 4 pièces (attendu : 2394 = 2394)
SELECT (SELECT SUM(credit) FROM transactions WHERE id IN ('dfc7665f-8484-4f6b-970b-51631845a41d','ed99427e-60a6-4225-ac01-675863641be1','b66ddc23-68e5-4ed8-837f-e38ae118ea72')) AS total_virements,
       (SELECT SUM(COALESCE(debit,0)-COALESCE(credit,0)) FROM journal_comptable WHERE piece IN ('ADH-58118248-ENC','ADH-81ffca8e-ENC','ADH-b7e0add0-ENC','REG-CHQ-2526') AND compte LIKE '512%') AS total_512_pieces;
-- 4g. solde du 411 de l'exercice 2025-2026 : attendu 0 (avant : 1025 après le groupe A-G, puis -180 Pass Région, -60 virement, -785 chèques)
SELECT ROUND(SUM(COALESCE(debit,0)-COALESCE(credit,0)),2) AS solde_411_2025_2026 FROM journal_comptable WHERE compte LIKE '411%' AND exercice_id = '4c7ef360-e2bb-449b-bb40-e4715dcd8b2e';
-- 4h. 2026-2027 : lignes créées par ce script (attendu : 6 lignes = 3 pièces)
SELECT piece, date_op, compte, debit, credit FROM journal_comptable WHERE source_logiciel = 'script-reglements-2025' AND date_op >= '2026-07-01' ORDER BY piece, compte;
-- 4i. Aragon 2026-2027 : attendu 0 (aucune ligne de ces pièces n'est créée ni modifiée par ce script)
SELECT COUNT(*) AS lignes_aragon_2026_2027_touchees FROM journal_comptable WHERE source_logiciel = 'script-reglements-2025' AND (piece LIKE 'ADH-b0cd371f%' OR piece LIKE 'PAY-F2D01A83%' OR piece LIKE 'VTE-50e923a5%');
-- 4j. solde du 411 de l'exercice 2026-2027 : attendu 15 (inchangé par ce script)
SELECT ROUND(SUM(COALESCE(debit,0)-COALESCE(credit,0)),2) AS solde_411_2026_2027 FROM journal_comptable WHERE compte LIKE '411%' AND exercice_id = '1c8cdf72-5240-4e1a-b9c1-c4f1e4ed2fbc';

-- 4k. Pass Région restant : attendu 1 ligne 512 de 60 € (pièce en attente du relevé bancaire : aucun virement ne la référence)
SELECT piece, date_op, debit FROM journal_comptable WHERE piece = 'REG-PAS-2526' AND compte LIKE '512%';
-- 4l. Elizeon : attendu 3 lignes dont 754 Dons manuels 40 € et AUCUNE ligne 471
SELECT piece, compte, debit, credit FROM journal_comptable WHERE piece = 'REG-875d1dcf' ORDER BY compte;

